    'home_a2521eac95bf' => ['text' => 'People use search engines to find products and answers to their problems. We fine-tune your site’s technical setup, build authority with content, and help you show up in both traditional rankings and Al-powered results so that more people can find and choose you.', 'rich' => 'People use search engines to find products and answers to their problems. We fine-tune your site’s technical setup, build authority with content, and help you show up in both traditional rankings and Al-powered results so that more people can find and choose you.', 'scope' => 'page', 'uppercase' => ''],
