    'search_engine_marketing_c14dc679be7b' => ['text' => 'Papaya Search isn’t just a regular partner. We’re a Google Partner, and we’ve been Google Ads certified since 2006. That means that Google recognizes us as experts in search engine advertising.', 'rich' => 'Papaya Search isn’t just a regular partner. <strong>We’re a Google Partner</strong>, and we’ve been Google Ads certified since 2006. That means that Google recognizes us as experts in search engine advertising.', 'scope' => 'page', 'uppercase' => ''],
